'use strict';
// V58.1 : negociations et historique pur, sans ecriture dans la sauvegarde du jeu.
(function(root,factory){const api=factory(typeof module==='object'&&module.exports?require('./coach-career.js'):root.CDCoachCareer);if(typeof module==='object'&&module.exports)module.exports=api;if(root)root.CDCoachNegotiations=api})(typeof globalThis==='object'?globalThis:null,function(career){
const clone=x=>JSON.parse(JSON.stringify(x));const check=(v,m)=>{if(!v)throw Error(m)};
const money=n=>typeof n==='number'&&Number.isFinite(n)&&n>=0;
function create(managerId,reputation=50){check(typeof managerId==='string'&&managerId&&money(reputation)&&reputation<=100,'Manager invalide');return {version:1,managerId,reputation,applications:[],offers:[],contracts:[],history:[],events:[]};}
function validate(s){check(s&&s.version===1&&typeof s.managerId==='string'&&money(s.reputation)&&s.reputation<=100&&Array.isArray(s.applications)&&Array.isArray(s.offers)&&Array.isArray(s.contracts)&&Array.isArray(s.history)&&Array.isArray(s.events),'Etat invalide');check(new Set(s.offers.map(x=>x.id)).size===s.offers.length,'Offres dupliquees');return true;}
function apply(s,a){validate(s);check(a&&Number.isInteger(a.season)&&a.season>0,'Saison invalide');const n=clone(s);let event;
if(a.type==='apply'){check(typeof a.clubId==='string'&&a.clubId&&!n.applications.some(x=>x.clubId===a.clubId&&x.season===a.season),'Candidature en double');n.applications.push({clubId:a.clubId,season:a.season,status:'pending'});event={type:'apply',clubId:a.clubId,season:a.season};}
else if(a.type==='offer'){check(typeof a.id==='string'&&a.id&&!n.offers.some(x=>x.id===a.id)&&typeof a.clubId==='string'&&a.clubId&&money(a.salary)&&Number.isInteger(a.years)&&a.years>=1&&a.years<=5,'Offre invalide');n.offers.push({id:a.id,clubId:a.clubId,salary:a.salary,years:a.years,expires:a.season+1,status:'pending'});event={type:'offer',offerId:a.id,season:a.season};}
else if(a.type==='counter'){const o=n.offers.find(x=>x.id===a.offerId);check(o&&o.status==='pending'&&a.season<=o.expires&&money(a.salary)&&Number.isInteger(a.years)&&a.years>=1&&a.years<=5,'Contre-offre invalide');o.counter={salary:a.salary,years:a.years};event={type:'counter',offerId:o.id,season:a.season};}
else if(a.type==='reject'){const o=n.offers.find(x=>x.id===a.offerId);check(o&&o.status==='pending','Offre indisponible');o.status='rejected';event={type:'reject',offerId:o.id,season:a.season};}
else if(a.type==='accept'){const o=n.offers.find(x=>x.id===a.offerId);check(o&&o.status==='pending'&&a.season<=o.expires,'Offre expiree');const salary=o.counter?.salary??o.salary,years=o.counter?.years??o.years;check(money(a.salaryCap)&&salary<=a.salaryCap,'Budget insuffisant');for(const c of n.contracts)if(c.status==='active'){c.status='resigned';n.history.push({clubId:c.clubId,end:a.season,reason:'resignation'});}o.status='accepted';n.offers.filter(x=>x.id!==o.id&&x.status==='pending').forEach(x=>x.status='declined');n.contracts.push({clubId:o.clubId,from:a.season,until:a.season+years,salary,status:'active'});n.reputation=Math.min(100,n.reputation+2);event={type:'accept',clubId:o.clubId,season:a.season,salary};}
else if(a.type==='dismiss'||a.type==='resign'){const c=n.contracts.find(x=>x.status==='active');check(c,'Aucun contrat actif');c.status=a.type==='dismiss'?'dismissed':'resigned';n.history.push({clubId:c.clubId,end:a.season,reason:a.type});n.reputation=Math.max(0,Math.min(100,n.reputation+(a.type==='dismiss'?-8:-3)));event={type:a.type,clubId:c.clubId,season:a.season};}
else if(a.type==='review'){check(Number.isInteger(a.performance)&&a.performance>=-20&&a.performance<=20,'Performance invalide');n.reputation=Math.max(0,Math.min(100,n.reputation+a.performance));event={type:'review',season:a.season,performance:a.performance};}
else throw Error('Action inconnue');
n.events.push(event);validate(n);return {state:n,event};}
function select(candidates,club){check(Array.isArray(candidates)&&club&&typeof club.id==='string'&&money(club.budget)&&money(club.reputation),'Selection invalide');return candidates.filter(x=>x&&money(x.salary)&&x.salary<=club.budget&&money(x.reputation)&&x.reputation<=100).sort((a,b)=>Math.abs(a.reputation-club.reputation)-Math.abs(b.reputation-club.reputation)||a.id.localeCompare(b.id))[0]?.id??null;}
return Object.freeze({create,validate,apply,select,career});
});
